<section class="archive-head"><span>Archive</span><h1><?= e($archiveTitle??'Blog') ?></h1><p><?= e($settings['site_description']??'Latest articles and updates.') ?></p></section><section class="posts archive"><?php foreach($posts as $post):?><article class="post-card"><div class="post-inner"><div class="date"><?= e(substr((string)$post['published_at'],0,10)) ?></div><h2><a href="/blog/<?= e($post['slug']) ?>"><?= e($post['title']) ?></a></h2><p><?= e($post['excerpt']?:'Continue reading…') ?></p></div></article><?php endforeach;?><?php if(!$posts):?><div class="empty">Nothing published here yet.</div><?php endif;?></section><?php if(($pagination['pages']??1)>1):?><nav class="pager"><?php for($i=1;$i<=$pagination['pages'];$i++):?><a class="<?= $i===$pagination['page']?'active':'' ?>" href="?page=<?= $i ?>"><?= $i ?></a><?php endfor;?></nav><?php endif;?>